  ['공간',     c => has(c,'편인'),             t => mb(t,'S','P'),                z => z.element==='흙'],
  ['신체',     c => has(c,'비견','겁재'),       t => mb(t,'S','P'),                z => z.element==='불' || z.modality==='활동'],
  ['음악',     c => has(c,'식신','상관'),       t => mbAny(t,'F'),                z => z.element==='물' || ['황소자리','천칭자리'].includes(z.sign)],
