  ['창의',     c => has(c,'상관','편인'),       t => mb(t,'N','P'),                z => z.element==='불' || z.element==='물'],
  ['실행력',   c => has(c,'비견','겁재','편관'), t => mbAny(t,'J') && mbAny(t,'T','E'), z => z.modality==='활동' || z.element==='불'],
