  물고기자리: '공감과 상상의 예술혼. 경계 없이 스며드는 감성가.',
};

const ELEMENT_LABEL = { 불: '불 🔥', 흙: '흙 🌱', 공기: '공기 💨', 물: '물 💧' };
const MODALITY_LABEL = { 활동: '활동궁(시작)', 고정: '고정궁(유지)', 변통: '변통궁(적응)' };

export function zodiacDetail(sign) {
  const t = TRAITS_LOOKUP[sign];
