}

export function renderCompat(result) {
  const { totalPercent, systems, goodPoints, frictionPoints, signA, signB } = result;
  const mood = totalPercent >= 75 ? '천생연분 흐름' : totalPercent >= 55 ? '잘 굴러가는 사이' : '서로 노력이 필요한 사이';
