(async () => {
  const { buildProfileCardSVG, CARD_W, CARD_H } = await import('/src/shareCard.js');
  const { runEngine } = await import('/src/engine.js');
  const result = runEngine({ birth:{year:1990,month:5,day:15,hour:10,calendar:'solar',gender:'male'}, mbti:'ENTJ', blood:'O', selectedStrengths:['논리','실행력','분석'] });
  const svg = buildProfileCardSVG(result);
  // rasterize like share.js does
  const blob = new Blob([svg], { type:'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const png = await new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      c.width = CARD_W*2; c.height = CARD_H*2;
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      try { c.toBlob(b => res({ ok:!!b, size:b?.size, w:c.width, h:c.height }), 'image/png'); }
      catch(e){ rej(e); }
    };
    img.onerror = () => rej(new Error('svg load fail'));
    img.src = url;
  });
  URL.revokeObjectURL(url);
  return png;
})()

