    hidden.forEach(n => { html += `<p><b>${n}</b> ${STRENGTH_TEXT[n] || ''} 정작 너는 꼽지 않았지만 여러 렌즈가 가리키는 자원이다. 의식적으로 한 번 꺼내 쓰기 시작하면, 생각보다 큰 힘이 되어줄 수 있다.</p>`; });
