    nurtured.forEach(n => { html += `<p><b>${n}</b> ${STRENGTH_TEXT[n] || ''} 타고난 신호는 옅지만, 네가 스스로 택해 갈고닦아온 강점이다. 타고남이 아니라 노력으로 빚은 힘이라 오히려 더 값지다.</p>`; });
