import { AXES } from './axes.js';
import { computeAxis } from './consensus.js';
import { mbtiSignals } from './mbti.js';
import { sunSign, zodiacSignals } from './zodiac.js';
import { bloodSignals } from './bloodtype.js';
import { sajuSignals, sajuDayElement } from './saju.js';
import { strengthCounts } from './strengths.js';
import { analyzeName } from './nameology.js';
import { analyzeDigitRatio } from './digitRatio.js';
import { analyzeFortune } from './fortune.js';

const BASE_WEIGHT = { 사주:1.0, MBTI:1.0, 별자리:0.6, 혈액형:0.3 };

export function runEngine(input) {
  const { birth, mbti, blood, name, digit } = input;

  const saju = sajuSignals(birth);
  const sajuCounts = saju.counts;
  const dayElement = sajuDayElement(birth);
  const sign = sunSign(birth.month, birth.day);
  const sys = {
    사주: saju.signals,
    MBTI: mbtiSignals(mbti),
    별자리: zodiacSignals(sign),
    혈액형: bloodSignals(blood),
  };
  const weight = { ...BASE_WEIGHT, 사주: saju.timeUnknown ? 0.85 : 1.0 };

  const axes = AXES.map(meta => {
    const entries = Object.keys(sys).map(system => ({
      system,
      signal: sys[system][meta.id],
      weight: weight[system],
      counted: system !== '혈액형',
    }));
    const r = computeAxis(entries);
    const poleLabel = r.resultPole > 0 ? meta.plus : r.resultPole < 0 ? meta.minus : '균형';
    return { ...meta, ...r, poleLabel };
  });

  const strengths = strengthCounts({ sajuCounts, mbti, sign });
  const nameAnalysis = name ? analyzeName(name, dayElement) : null;
  const digitAnalysis = analyzeDigitRatio(digit);

  return { axes, strengths, sajuTimeUnknown: saju.timeUnknown, sunSign: sign, dayElement, name: nameAnalysis, digit: digitAnalysis };
}

import { renderRadarSVG } from './radar.js';
import { zodiacDetail } from './zodiacInfo.js';
import { revealedCard } from './tarotView.js';
import { temperamentNarrative, strengthNarrative, timeNarrative, nameNarrative, digitNarrative } from './narrative.js';

const stars = n => '★'.repeat(n) + '☆'.repeat(Math.max(0, 3 - n));

function catchphrase(axes) {
  // ★★★ = 3개 시스템(렌즈) 일치. 그 축들의 극을 캐치프레이즈로.
  const strong = axes.filter(a => a.stars >= 3 && a.resultPole !== 0);
  if (strong.length) {
    return `세 렌즈가 한 곳을 가리키는 너,<br><span class="hl">${strong.map(a => a.poleLabel).join(' · ')}</span>`;
  }
  const twos = axes.filter(a => a.stars >= 2 && a.resultPole !== 0);
  if (twos.length) {
    return `여러 렌즈가 겹쳐 보이는 너,<br><span class="hl">${twos.map(a => a.poleLabel).join(' · ')}</span>`;
  }
  if (axes.some(a => a.conflict)) {
    return `여러 렌즈가 엇갈리는,<br><span class="hl">단순하지 않은 입체적인 너</span>`;
  }
  return `여러 렌즈로 비춰 본<br><span class="hl">너의 통합 프로파일</span>`;
}

function systemChips(list) {
  if (!list.length) return `<span class="chip muted">신호 약함</span>`;
  return list.map(s => `<span class="chip">${s}</span>`).join('');
}

function axisCard(a) {
  const conflict = a.conflict ? `<span class="tag conflict">충돌 · 입체</span>` : '';
  return `<div class="axis-card">
    <div class="axis-head">
      <span class="axis-label">${a.label}</span>
      <span class="axis-pole">${a.poleLabel}</span>
      <span class="badge" title="근거 시스템 ${a.stars}개">${stars(a.stars)}</span>
    </div>
    <div class="axis-foot">${systemChips(a.contributingSystems)}${conflict}</div>
  </div>`;
}

function strengthChips(strengths) {
  const ranked = [...strengths].sort((a, b) => b.count - a.count);
  return ranked.map(s => {
    const cls = s.count >= 3 ? 'gold' : s.count === 2 ? 'silver' : s.count === 1 ? 'bronze' : 'zero';
    return `<span class="s-chip ${cls}">${s.name}<i>${s.count}</i></span>`;
  }).join('');
}

