86	export function strengthNarrative(result) {
87	  const ranked = [...result.strengths].sort((a, b) => b.count - a.count);
88	  const strong = ranked.filter(s => s.count >= 2);
89	  const mild = ranked.filter(s => s.count === 1);
90	  let html = '';
91	  if (strong.length) {
92	    html += `<p class="nv-head nv-confirm">⭐ 여러 렌즈가 함께 가리키는 핵심 강점</p>`;
93	    strong.forEach(s => {
94	      html += `<p><b>${s.name}</b> <span class="nv-src">${s.systems.join(' · ')}</span><br>${STRENGTH_TEXT[s.name] || ''} ${s.count}개의 렌즈가 동시에 이 자질을 비추니, 믿고 밀어붙여도 좋은 너의 무기다.</p>`;
95	    });
96	  }
97	  if (mild.length) {
98	    html += `<p class="nv-head">🔹 한 렌즈에서 비치는 잠재 강점</p>`;
99	    html += `<p>${mild.map(s => s.name).join(' · ')} — 아직 한 시스템에서만 신호가 잡히지만, 의식적으로 키우면 충분히 너의 무기가 될 수 있는 씨앗들이다.</p>`;
100	  }
101	  if (!html) html = '<p>아직 뚜렷하게 합의된 강점이 옅다. 여러 영역을 폭넓게 시도하며 너만의 무기를 찾아가는 시기다.</p>';
102	  return html;
103	}
104	
105	// ===== 성명학 서술 =====
106	export function nameNarrative(n) {
107	  if (!n) return '';
108	  let html = `<p>이름 <b>${esc(n.raw)}</b>을(를) 소리오행(發音五行)으로 풀어본다. 각 글자의 첫소리가 품은 기운은 이렇다.</p>`;
109	  html += `<p>${n.syllables.map(s => `<b>${esc(s.char)}</b> → ${s.element}(${s.choseong})`).join(' &nbsp; ')}</p>`;
110	  if (n.flow.length) {
111	    const good = n.flow.filter(f => f.relation === '상생').length;
112	    const bad = n.flow.filter(f => f.relation === '상극').length;
113	    html += `<p><b>글자 사이 기운의 흐름</b><br>` +
114	      n.flow.map(f => `${f.from}→${f.to} <b>${f.relation}</b> — ${f.note}`).join('<br>') + `</p>`;
115	    const verdict = good > bad ? '서로 북돋우는 기운이 우세해, 이름이 순하게 흐른다.'
116	      : bad > good ? '부딪히는 기운이 섞여 있어, 그만큼 자기 색이 강하고 굴곡이 있는 이름이다.'
117	      : '생과 극이 균형을 이뤄, 안정과 자극을 함께 품은 이름이다.';
118	    html += `<p>${verdict}</p>`;
119	  }
120	  if (n.sajuRelation) {
121	    html += `<p><b>사주와의 어울림</b><br>${n.sajuRelation.note} — <b>${n.sajuRelation.verdict}</b>.</p>`;
122	  }
123	  html += `<p class="nv-foot">한글 초성 소리오행 기준의 재미용 풀이입니다. 한자 획수·수리(數理) 정밀 해석은 포함하지 않았어요.</p>`;
124	  return html;
125	}
