127	// ===== 손가락 비율(2D:4D) 서술 =====
128	export function digitNarrative(d) {
129	  if (!d) return '';
130	  let html = `<p><b>${esc(d.category)}</b> 유형이다. 태내 테스토스테론 노출은 <b>${esc(d.testosterone)}</b>으로 추정된다.</p>`;
131	  html += `<p>${esc(d.blurb)}</p>`;
132	  html += `<p>느슨하게 연관되는 키워드: <b>${d.traits.map(esc).join(' · ')}</b></p>`;
133	  html += `<p class="nv-foot">2D:4D는 상관 연구에 기반한 지표로 학계 논쟁이 있고 개인차가 큽니다. 재미로만 참고하세요.</p>`;
134	  return html;
135	}
