155	// ===== 타로 시간축 서술 (메이저 22 × 정/역) =====
156	const TAROT_LONG = {
157	  0:  { up: '겁 없이 첫발을 내딛던 순수한 모험의 기운이 흐른다. 정해진 길이 없다는 건 곧 무엇이든 될 수 있다는 뜻이었다.', down: '준비 없이 뛰어들어 휘청였거나, 두려움에 발이 묶여 시작을 미뤘던 시간이다.' },
158	  1:  { up: '가진 재료를 능숙하게 다루어 원하는 것을 현실로 빚어내는 힘이 발휘됐다. 의지가 곧 길이 되던 때다.', down: '재능을 제대로 쓰지 못했거나, 말과 겉모습이 앞서 알맹이가 비었던 흐름이다.' },
159	  2:  { up: '겉으로 드러나지 않는 직관과 내면의 지혜가 작동했다. 답은 바깥이 아니라 너의 안에 고요히 있었다.', down: '마음의 소리를 외면했거나, 드러나지 않은 비밀과 혼란이 발목을 잡았다.' },
160	  3:  { up: '풍요와 돌봄, 무언가를 길러내는 너그러운 기운이 가득했다. 마음을 쏟은 것들이 자라나던 시기다.', down: '베풂이 의존으로 기울었거나, 창조의 흐름이 막혀 정체됐던 때다.' },
161	  4:  { up: '질서를 세우고 책임을 짊어지는 단단한 기운이 있었다. 스스로 기준이 되어 판을 안정시켰다.', down: '고집과 통제가 지나쳐 경직됐거나, 기댈 울타리가 흔들렸던 흐름이다.' },
