187	export function timeNarrative(spread) {
188	  if (!spread || !spread.length) return '';
189	  let html = '';
190	  spread.forEach(s => {
191	    const long = TAROT_LONG[s.card.id] || { up: s.card.upright, down: s.card.reversed };
192	    const body = s.reversed ? long.down : long.up;
193	    const orient = s.reversed ? '역방향' : '정방향';
194	    html += `<p><b>${s.position} · ${s.card.emoji} ${s.card.name} (${orient})</b><br>${POS_FRAME[s.position] || ''}${body}</p>`;
195	  });
196	  html += '<p class="nv-foot">기억하자 — 타로의 미래는 정해진 운명이 아니라, 지금 너의 선택으로 얼마든지 다시 쓸 수 있는 가능성의 지도다.</p>';
197	  return html;
198	}
