  const tgChips = Array.from(card.querySelectorAll('.tg-chip')).map(c => c.textContent.trim());
  const narrativeP = card.querySelector('.narrative p')?.textContent.slice(0,60);
  return { thTexts, ganTexts, ohRows, tgChips, narrativeP };
})()

