107	export function nameNarrative(n) {
108	  if (!n) return '';
109	  let html = `<p>이름 <b>${esc(n.raw)}</b>을(를) 소리오행(發音五行)으로 풀어본다. 각 글자의 첫소리가 품은 기운은 이렇다.</p>`;
110	  html += `<p>${n.syllables.map(s => `<b>${esc(s.char)}</b> → ${s.element}(${s.choseong})`).join(' &nbsp; ')}</p>`;
111	  if (n.flow.length) {
112	    const good = n.flow.filter(f => f.relation === '상생').length;
113	    const bad = n.flow.filter(f => f.relation === '상극').length;
114	    html += `<p><b>글자 사이 기운의 흐름</b><br>` +
115	      n.flow.map(f => `${f.from}→${f.to} <b>${f.relation}</b> — ${f.note}`).join('<br>') + `</p>`;
116	    const verdict = good > bad ? '서로 북돋우는 기운이 우세해, 이름이 순하게 흐른다.'
117	      : bad > good ? '부딪히는 기운이 섞여 있어, 그만큼 자기 색이 강하고 굴곡이 있는 이름이다.'
118	      : '생과 극이 균형을 이뤄, 안정과 자극을 함께 품은 이름이다.';
119	    html += `<p>${verdict}</p>`;
120	  }
121	  if (n.sajuRelation) {
122	    html += `<p><b>사주와의 어울림</b><br>${n.sajuRelation.note} — <b>${n.sajuRelation.verdict}</b>.</p>`;
123	  }
124	  html += `<p class="nv-foot">한글 초성 소리오행 기준의 재미용 풀이입니다. 한자 획수·수리(數理) 정밀 해석은 포함하지 않았어요.</p>`;
125	  return html;
126	}
