   export function sajuNarrative(detail) {
     if (!detail) return '';
     const { pillars, ohaeng, tenGodGroups } = detail;
     const p = pillars.dayProfile;
     let html = '';

     // ① 일간 기질
     html += `<p class="nv-head">⚡ 일간(日干) ${pillars.dayGan} · ${p.symbol}</p>`;
     html += `<p>핵심 기질: <b>${p.core}</b><br>${p.text}</p>`;

