1	// 운세 시각화 (의존성 없는 SVG/HTML 문자열)
2	
3	const ICON = { 재물: '💰', 성공: '🏆', 연애: '💕', 건강: '🌿' };
4	
5	export function renderFortuneBars(natal) {
6	  return `<div class="f-bars">` + Object.entries(natal).map(([k, v]) => `
7	    <div class="f-row">
8	      <span class="f-name">${ICON[k] || ''} ${k}운</span>
9	      <span class="f-bar"><i style="width:${v}%"></i></span>
10	      <span class="f-score">${v}</span>
11	    </div>`).join('') + `</div>`;
12	}
13	
14	const W = 680, H = 250, PADL = 34, PADR = 18, PADT = 26, PADB = 52;
15	const VMIN = 15, VMAX = 97;
16	
17	export function renderLifeGraph(timeline) {
18	  const periods = timeline.periods || [];
19	  if (periods.length < 2) {
20	    return `<p class="note">대운 정보를 계산할 수 없어 인생 흐름 그래프는 생략됐습니다(출생 정보 확인).</p>`;
21	  }
22	  const n = periods.length;
23	  const x = i => PADL + i * (W - PADL - PADR) / (n - 1);
24	  const y = v => PADT + (1 - (v - VMIN) / (VMAX - VMIN)) * (H - PADT - PADB);
25	
26	  // 가로 기준선
27	  let grid = '';
28	  [25, 50, 75].forEach(v => {
29	    grid += `<line x1="${PADL}" y1="${y(v).toFixed(1)}" x2="${W - PADR}" y2="${y(v).toFixed(1)}" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>`;
30	  });
31	
32	  const pts = periods.map((p, i) => [x(i), y(p.overall)]);
33	  const path = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
34	  // 면적 채우기
35	  const area = `M${pts[0][0].toFixed(1)},${(H - PADB).toFixed(1)} ` +
36	    pts.map(p => `L${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ') +
37	    ` L${pts[n - 1][0].toFixed(1)},${(H - PADB).toFixed(1)} Z`;
38	
39	  let dots = '', labels = '';
40	  periods.forEach((p, i) => {
41	    const isLow = (timeline.lows || []).includes(p.startAge);
42	    const isPeak = timeline.peak === p.startAge;
43	    const color = isLow ? '#ff8a8a' : isPeak ? '#f0c75e' : '#cdc7f0';
44	    const r = isLow || isPeak ? 6 : 4;
45	    dots += `<circle cx="${pts[i][0].toFixed(1)}" cy="${pts[i][1].toFixed(1)}" r="${r}" fill="${color}"/>`;
46	    if (isLow) labels += `<text x="${pts[i][0].toFixed(1)}" y="${(pts[i][1] - 12).toFixed(1)}" text-anchor="middle" fill="#ff8a8a" font-size="12" font-weight="700">고비</text>`;
47	    if (isPeak) labels += `<text x="${pts[i][0].toFixed(1)}" y="${(pts[i][1] - 12).toFixed(1)}" text-anchor="middle" fill="#f0c75e" font-size="12" font-weight="700">전성기</text>`;
48	    // 나이 축
49	    labels += `<text x="${pts[i][0].toFixed(1)}" y="${(H - PADB + 20).toFixed(1)}" text-anchor="middle" fill="#a39fc8" font-size="11">${p.startAge}세</text>`;
50	  });
51	
52	  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="인생 운세 흐름 그래프" xmlns="http://www.w3.org/2000/svg">
53	    ${grid}
54	    <path d="${area}" fill="rgba(240,199,94,0.12)"/>
55	    <path d="${path}" fill="none" stroke="#f0c75e" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>
56	    ${dots}
57	    ${labels}
58	  </svg>`;
59	}
60

