      if (!god) return;
      periods.push({
        startAge: dy.getStartAge(),
        ganZhi: gz,
        tenGod: god,
        label: TENGOD_LABEL[god] || '',
        overall: clamp(50 + (TENGOD_FORTUNE[god] || 0)),
      });
