    const lows = periods.filter(p => p.overall === minV).map(p => p.startAge);
    const peak = periods.find(p => p.overall === maxV) || null;
    return { periods, lows, peak: peak ? peak.startAge : null, minV, maxV };
  } catch (e) {
    return { periods: [], lows: [], peak: null };
  }
}

