import { runEngine } from './engine.js';
import { renderReport } from './report.js';
import { analyzeCompat } from './compat.js';
import { renderCompat } from './compatReport.js';
import { drawThree } from './tarot.js';
import { renderTarotBoard, revealedCard } from './tarotView.js';
import { buildProfileCardSVG, buildCompatCardSVG } from './shareCard.js';
import { downloadSVGAsPNG } from './share.js';

function bindShare(btnId, svgString, filename) {
  const btn = document.getElementById(btnId);
  if (!btn) return;
  btn.addEventListener('click', async () => {
    const orig = btn.textContent;
    btn.disabled = true; btn.textContent = '이미지 만드는 중…';
    try { await downloadSVGAsPNG(svgString, filename); btn.textContent = '저장 완료 ✓'; }
    catch (e) { console.error(e); btn.textContent = '저장 실패'; }
    finally { setTimeout(() => { btn.disabled = false; btn.textContent = orig; }, 1500); }
  });
}

const MBTIS = ['INTJ','INTP','ENTJ','ENTP','INFJ','INFP','ENFJ','ENFP',
  'ISTJ','ISFJ','ESTJ','ESFJ','ISTP','ISFP','ESTP','ESFP'];

function fillMbti(sel, withPlaceholder) {
  if (withPlaceholder) sel.add(new Option('선택', '', true, true));
  MBTIS.forEach(m => sel.add(new Option(m, m)));
}

// 타로 보드를 container에 띄우고, 3장 선택이 끝나면 onComplete(spread) 호출.
function runTarotPick(container, onComplete) {
  const spread = drawThree(Math.random); // 3장 미리 결정(과거/현재/미래)
  container.innerHTML = renderTarotBoard();
  const pickCountEl = container.querySelector('#pick-count');
  const slotsEl = container.querySelector('#picked-slots');
  let picked = 0;
  container.querySelectorAll('.tcard.back').forEach(btn => btn.addEventListener('click', () => {
    if (btn.disabled || picked >= 3) return;
    btn.disabled = true;
    slotsEl.insertAdjacentHTML('beforeend', revealedCard(spread[picked]));
    picked += 1;
    pickCountEl.textContent = String(picked);
    if (picked === 3) setTimeout(() => onComplete(spread), 700);
  }));
  container.querySelector('#tarot-board')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ===== 탭 네비게이션 =====
const navButtons = document.querySelectorAll('.nav button');
const views = document.querySelectorAll('.view');
navButtons.forEach(btn => btn.addEventListener('click', () => {
  navButtons.forEach(b => b.classList.toggle('active', b === btn));
  const target = btn.dataset.view;
  views.forEach(v => v.classList.toggle('active', v.id === `view-${target}`));
  window.scrollTo({ top: 0, behavior: 'smooth' });
}));

// ===== 프로파일 (입력 → 타로 → 통합 결과) =====
const mbtiSel = document.getElementById('mbti');
fillMbti(mbtiSel, true);
const nameInput = document.getElementById('name');

const hourUnknown = document.getElementById('hourUnknown');
hourUnknown.addEventListener('change', () => { document.getElementById('hour').disabled = hourUnknown.checked; });

const resultEl = document.getElementById('result');

function showProfileResult(input, spread) {
  try {
    const result = runEngine(input);
    resultEl.innerHTML = renderReport(result, spread);
    bindShare('share-btn', buildProfileCardSVG(result, spread), 'penta-profile.png');
    const r = document.getElementById('restart-btn');
    if (r) r.addEventListener('click', () => { resultEl.innerHTML = ''; window.scrollTo({ top: 0, behavior: 'smooth' }); });
    document.getElementById('report')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } catch (err) {
    resultEl.innerHTML = `<p class="note">분석 오류: ${err.message}</p>`; console.error(err);
  }
}

document.getElementById('penta-form').addEventListener('submit', (e) => {
  e.preventDefault();
  if (!mbtiSel.value) { alert('MBTI를 선택하세요.'); return; }
  const input = {
    birth: {
      year: +document.getElementById('year').value, month: +document.getElementById('month').value,
      day: +document.getElementById('day').value,
      hour: hourUnknown.checked ? null : +document.getElementById('hour').value,
      calendar: document.querySelector('input[name=cal]:checked').value,
      gender: document.querySelector('input[name=gender]:checked').value,
    },
    mbti: mbtiSel.value, blood: document.getElementById('blood').value, name: nameInput.value.trim(),
    digit: document.getElementById('digit').value,
  };
  // 입력 확정 → 타로 3장 뽑기 → 통합 결과
  runTarotPick(resultEl, (spread) => showProfileResult(input, spread));
});

// ===== 궁합 =====
document.querySelectorAll('#compat-form .c-mbti').forEach(sel => fillMbti(sel, true));
const compatResultEl = document.getElementById('compat-result');

function readPerson(scope) {
  return {
    birth: {
      year: +scope.querySelector('.c-year').value, month: +scope.querySelector('.c-month').value,
      day: +scope.querySelector('.c-day').value, hour: null, calendar: 'solar', gender: 'male',
    },
    mbti: scope.querySelector('.c-mbti').value,
    blood: scope.querySelector('.c-blood').value,
  };
}
document.getElementById('compat-form').addEventListener('submit', (e) => {
  e.preventDefault();
  const blocks = document.querySelectorAll('#compat-form .person-block');
  try {
    const result = analyzeCompat(readPerson(blocks[0]), readPerson(blocks[1]));
    compatResultEl.innerHTML = renderCompat(result);
    bindShare('compat-share-btn', buildCompatCardSVG(result), 'penta-compat.png');
    const rb = document.getElementById('compat-restart');
    if (rb) rb.addEventListener('click', () => { compatResultEl.innerHTML = ''; window.scrollTo({ top: 0, behavior: 'smooth' }); });
    document.getElementById('compat-report')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } catch (err) {
    compatResultEl.innerHTML = `<p class="note">궁합 분석 오류: ${err.message}</p>`; console.error(err);
  }
});

import { renderRadarSVG } from './radar.js';
import { zodiacDetail } from './zodiacInfo.js';
import { revealedCard } from './tarotView.js';
import { temperamentNarrative, strengthNarrative, timeNarrative, nameNarrative, digitNarrative, fortuneNarrative, sajuNarrative, radarNarrative, synthesisNarrative, relationNarrative } from './narrative.js';
import { renderFortuneBars, renderLifeGraph, renderRelationBars } from './fortuneGraph.js';
import { OHAENG_COLOR } from './sajuDetail.js';

const stars = n => '★'.repeat(n) + '☆'.repeat(Math.max(0, 3 - n));

function catchphrase(axes) {
  // ★★★ = 3개 시스템(렌즈) 일치. 그 축들의 극을 캐치프레이즈로.
  const strong = axes.filter(a => a.stars >= 3 && a.resultPole !== 0);
  if (strong.length) {
    return `세 렌즈가 한 곳을 가리키는 너,<br><span class="hl">${strong.map(a => a.poleLabel).join(' · ')}</span>`;
  }
  const twos = axes.filter(a => a.stars >= 2 && a.resultPole !== 0);
  if (twos.length) {
    return `여러 렌즈가 겹쳐 보이는 너,<br><span class="hl">${twos.map(a => a.poleLabel).join(' · ')}</span>`;
  }
  if (axes.some(a => a.conflict)) {
    return `여러 렌즈가 엇갈리는,<br><span class="hl">단순하지 않은 입체적인 너</span>`;
  }
  return `여러 렌즈로 비춰 본<br><span class="hl">너의 통합 프로파일</span>`;
}

function systemChips(list) {
  if (!list.length) return `<span class="chip muted">신호 약함</span>`;
  return list.map(s => `<span class="chip">${s}</span>`).join('');
}

function axisCard(a) {
  const conflict = a.conflict ? `<span class="tag conflict">충돌 · 입체</span>` : '';
  return `<div class="axis-card">
    <div class="axis-head">
      <span class="axis-label">${a.label}</span>
      <span class="axis-pole">${a.poleLabel}</span>
      <span class="badge" title="근거 시스템 ${a.stars}개">${stars(a.stars)}</span>
    </div>
    <div class="axis-foot">${systemChips(a.contributingSystems)}${conflict}</div>
  </div>`;
}

function strengthChips(strengths) {
  const ranked = [...strengths].sort((a, b) => b.count - a.count);
  return ranked.map(s => {
    const cls = s.count >= 3 ? 'gold' : s.count === 2 ? 'silver' : s.count === 1 ? 'bronze' : 'zero';
    return `<span class="s-chip ${cls}">${s.name}<i>${s.count}</i></span>`;
  }).join('');
}

function sajuBlock(detail) {
  if (!detail) return '';
  const { pillars, ohaeng, tenGodGroups } = detail;

  // 사주 팔자 표
  const cols = [pillars.time, pillars.day, pillars.month, pillars.year].filter(Boolean);
  const headers = pillars.time
    ? ['시(時)', '일(日)', '월(月)', '년(年)']
    : ['일(日)', '월(月)', '년(年)'];
  const tableHtml = `<table class="saju-table">
    <tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>
    <tr>${cols.map(p => `<td class="saju-gan" style="color:${OHAENG_COLOR[p.ganEl]}">${p.ganKo}(${p.gan})</td>`).join('')}</tr>
    <tr>${cols.map(p => `<td class="saju-el">${p.ganEl}</td>`).join('')}</tr>
    <tr class="saju-sep"><td colspan="${cols.length}"></td></tr>
    <tr>${cols.map(p => `<td class="saju-zhi" style="color:${OHAENG_COLOR[p.zhiEl]}">${p.zhiKo}(${p.zhi})</td>`).join('')}</tr>
    <tr>${cols.map(p => `<td class="saju-el">${p.zhiEl} · ${p.animal}</td>`).join('')}</tr>
  </table>`;

  // 오행 균형 막대
  const total = Math.max(1, Object.values(ohaeng).reduce((a, b) => a + b, 0));
  const OHAENG_KO = { 목:'木 목', 화:'火 화', 토:'土 토', 금:'金 금', 수:'水 수' };
  const ohaengHtml = Object.entries(ohaeng).map(([el, cnt]) => {
    const pct = Math.round(cnt / total * 100);
    return `<div class="oh-row">
      <span class="oh-label">${OHAENG_KO[el]}</span>
      <div class="oh-track"><div class="oh-fill" style="width:${pct}%;background:${OHAENG_COLOR[el]}"></div></div>
      <span class="oh-cnt">${cnt}</span>
    </div>`;
  }).join('');

  // 십성 5그룹 칩
  const tgHtml = Object.entries(tenGodGroups).map(([g, cnt]) => {
    const cls = cnt >= 3 ? 'tg-high' : cnt >= 2 ? 'tg-mid' : cnt >= 1 ? 'tg-low' : 'tg-zero';
    return `<span class="tg-chip ${cls}">${g} <i>${cnt}</i></span>`;
  }).join('');

  const timeNote = pillars.timeUnknown
    ? '<p class="note">※ 출생 시간 미입력 — 시주(時柱) 제외</p>' : '';

  return `<div class="card">
    <h3>사주 풀이 <small>四柱八字 · 日主 분석</small></h3>
    <h4 class="f-sub">사주 팔자 (四柱八字)</h4>
    ${tableHtml}
    ${timeNote}
    <h4 class="f-sub">오행 균형 <small>천간·지지 합산</small></h4>
    <div class="oh-bars">${ohaengHtml}</div>
    <h4 class="f-sub">십성 분포 <small>비겁·식상·재성·관성·인성</small></h4>
    <div class="tg-chips">${tgHtml}</div>
    <div class="narrative" style="margin-top:14px">${sajuNarrative(detail)}</div>
  </div>`;
}

function fortuneBlock(f) {
  if (!f) return '';
  return `<div class="card">
    <h3>재물 · 성공 · 연애운 <small>+ 인생의 고비</small></h3>
    ${renderFortuneBars(f.natal)}
    <h4 class="f-sub">인생 운세 흐름 <small>10년 단위 대운</small></h4>
    <div class="life-graph">${renderLifeGraph(f.timeline)}</div>
    <div class="narrative">${fortuneNarrative(f)}</div>
  </div>`;
}

function relationBlock(fortune, sajuDetail) {
  if (!fortune?.relation) return '';
  return `<div class="card">
    <h3>가족 인연운 <small>배우자 · 자식 · 부모 · 형제</small></h3>
    ${renderRelationBars(fortune.relation)}
    <div class="narrative" style="margin-top:14px">${relationNarrative(fortune, sajuDetail)}</div>
  </div>`;
}

function digitBlock(d) {
  if (!d) return '';
  return `<div class="card">
    <h3>손가락 비율 <small>2D:4D · 태내 호르몬</small></h3>
    <div class="narrative">${digitNarrative(d)}</div>
  </div>`;
}

function nameBlock(nameAnalysis) {
  if (!nameAnalysis) return '';
  return `<div class="card">
    <h3>성명학 <small>소리오행 · 점수 ${nameAnalysis.score}</small></h3>
    <div class="narrative">${nameNarrative(nameAnalysis)}</div>
  </div>`;
}

function zodiacBlock(sunSign) {
  const z = zodiacDetail(sunSign);
  if (!z) return '';
  return `<div class="card zodiac-card">
    <h3>별자리 <small>${z.sign}</small></h3>
    <div class="z-meta">
      <span class="z-pill">${z.elementLabel}</span>
      <span class="z-pill">${z.modalityLabel}</span>
      <span class="z-pill">${z.polarity}(陰陽)</span>
    </div>
    <p class="z-blurb">${z.blurb}</p>
  </div>`;
}

function tarotBlock(spread) {
  if (!spread || !spread.length) return '';
  return `<div class="card">
    <h3>과거 · 현재 · 미래 <small>타로 시간축</small></h3>
    <div class="tresult">${spread.map(revealedCard).join('')}</div>
    <div class="narrative">${timeNarrative(spread)}</div>
  </div>`;
}

export function renderReport(result, spread) {
  const { axes, strengths, sajuTimeUnknown, sunSign } = result;
  const timeNote = sajuTimeUnknown
    ? `<p class="note">※ 시주(출생시) 없이 추정 — 내면·말년 영역 정밀도가 낮습니다.</p>` : '';

  return `
  <section class="report" id="report">
    <div class="hero">
      <p class="hero-sub">★★★ = 3개 렌즈 일치 · 신뢰도 배지</p>
      <h2 class="catch">${catchphrase(axes)}</h2>
      <p class="sun">☀ 태양궁 <b>${sunSign}</b></p>
    </div>

    <div class="card radar-card">
      <h3>일치도 레이더 <small>5축 성향 · ★ = 시스템 일치 수</small></h3>
      <div class="radar-wrap">${renderRadarSVG(axes)}</div>
      <div class="narrative" style="margin-top:12px">${radarNarrative(axes)}</div>
    </div>

    ${sajuBlock(result.sajuDetail)}

    ${zodiacBlock(sunSign)}

    <div class="card">
      <h3>성격 5축</h3>
      <div class="axis-grid">${axes.map(axisCard).join('')}</div>
    </div>

    <div class="card">
      <h3>타고난 기질 풀이</h3>
      <div class="narrative">${temperamentNarrative(result, result.dayElement)}</div>
    </div>

    ${digitBlock(result.digit)}

    <div class="card">
      <h3>강점 <small>(숫자 = 근거 시스템 수)</small></h3>
      <div class="s-grid">${strengthChips(strengths)}</div>
      <div class="narrative" style="margin-top:14px">${strengthNarrative(result)}</div>
    </div>

    ${fortuneBlock(result.fortune)}

    ${relationBlock(result.fortune, result.sajuDetail)}

    ${nameBlock(result.name)}

    ${tarotBlock(spread)}

    <div class="card synthesis-card">
      <h3>종합 의견 <small>5개 시스템 통합 분석</small></h3>
      <div class="narrative">${synthesisNarrative(result)}</div>
    </div>

    ${timeNote}
    <p class="disclaimer">이 결과는 <b>재미용 셀프 분석</b>입니다. 과학적·확정적 예측이 아닙니다.</p>

    <div class="actions">
      <button type="button" id="share-btn" class="submit" style="max-width:320px">📸 결과 이미지로 저장</button>
      <div style="margin-top:10px"><button type="button" id="restart-btn" class="ghost">다시 하기</button></div>
    </div>
  </section>`;
}

// 운세 시각화 (의존성 없는 SVG/HTML 문자열)

const ICON = { 재물: '💰', 성공: '🏆', 연애: '💕', 건강: '🌿' };
const REL_ICON = { 배우자: '💑', 자식: '👶', 부모: '🏠', 형제: '🤝' };

export function renderFortuneBars(natal) {
  return `<div class="f-bars">` + Object.entries(natal).map(([k, v]) => `
    <div class="f-row">
      <span class="f-name">${ICON[k] || ''} ${k}운</span>
      <span class="f-bar"><i style="width:${v}%"></i></span>
      <span class="f-score">${v}</span>
    </div>`).join('') + `</div>`;
}

export function renderRelationBars(relation) {
  return `<div class="f-bars">` + Object.entries(relation).map(([k, v]) => {
    const cls = v >= 68 ? 'rel-high' : v < 44 ? 'rel-low' : '';
    return `<div class="f-row">
      <span class="f-name">${REL_ICON[k] || ''} ${k}운</span>
      <span class="f-bar"><i class="${cls}" style="width:${v}%"></i></span>
      <span class="f-score">${v}</span>
    </div>`;
  }).join('') + `</div>`;
}

const W = 680, H = 250, PADL = 34, PADR = 18, PADT = 26, PADB = 52;
const VMIN = 15, VMAX = 97;

export function renderLifeGraph(timeline) {
  const periods = timeline.periods || [];
  if (periods.length < 2) {
    return `<p class="note">대운 정보를 계산할 수 없어 인생 흐름 그래프는 생략됐습니다(출생 정보 확인).</p>`;
  }
  const n = periods.length;
  const x = i => PADL + i * (W - PADL - PADR) / (n - 1);
  const y = v => PADT + (1 - (v - VMIN) / (VMAX - VMIN)) * (H - PADT - PADB);

  // 가로 기준선
  let grid = '';
  [25, 50, 75].forEach(v => {
    grid += `<line x1="${PADL}" y1="${y(v).toFixed(1)}" x2="${W - PADR}" y2="${y(v).toFixed(1)}" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>`;
  });

  const pts = periods.map((p, i) => [x(i), y(p.overall)]);
  const path = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
  // 면적 채우기
  const area = `M${pts[0][0].toFixed(1)},${(H - PADB).toFixed(1)} ` +
    pts.map(p => `L${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ') +
    ` L${pts[n - 1][0].toFixed(1)},${(H - PADB).toFixed(1)} Z`;

  let dots = '', labels = '';
  periods.forEach((p, i) => {
    const isLow = (timeline.lows || []).includes(p.startAge);
    const isPeak = timeline.peak === p.startAge;
    const color = isLow ? '#ff8a8a' : isPeak ? '#f0c75e' : '#cdc7f0';
    const r = isLow || isPeak ? 6 : 4;
    dots += `<circle cx="${pts[i][0].toFixed(1)}" cy="${pts[i][1].toFixed(1)}" r="${r}" fill="${color}"/>`;
    if (isLow) labels += `<text x="${pts[i][0].toFixed(1)}" y="${(pts[i][1] - 12).toFixed(1)}" text-anchor="middle" fill="#ff8a8a" font-size="12" font-weight="700">고비</text>`;
    if (isPeak) labels += `<text x="${pts[i][0].toFixed(1)}" y="${(pts[i][1] - 12).toFixed(1)}" text-anchor="middle" fill="#f0c75e" font-size="12" font-weight="700">전성기</text>`;
    // 나이 축
    labels += `<text x="${pts[i][0].toFixed(1)}" y="${(H - PADB + 20).toFixed(1)}" text-anchor="middle" fill="#a39fc8" font-size="11">${p.startAge}세</text>`;
  });

  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="인생 운세 흐름 그래프" xmlns="http://www.w3.org/2000/svg">
    ${grid}
    <path d="${area}" fill="rgba(240,199,94,0.12)"/>
    <path d="${path}" fill="none" stroke="#f0c75e" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>
    ${dots}
    ${labels}
  </svg>`;
}

