      <div class="axis-grid">${axes.map(axisCard).join('')}</div>
    </div>

    <div class="card">
      <h3>타고난 기질 풀이</h3>
      <div class="narrative">${temperamentNarrative(result, result.dayElement)}</div>
    </div>

    ${digitBlock(result.digit)}

