380	function incomeParadox(tgs) {
381	  const jae = tgs.재성 || 0, gwan = tgs.관성 || 0,
382	        sik = tgs.식상 || 0, in_ = tgs.인성 || 0, bi = tgs.비겁 || 0;
383	
384	  if (jae >= 2 && gwan <= 1)
385	    return `재성은 강한데 관성이 약한 구조다. 돈 감각은 타고났지만 조직의 틀 안에서는 그 감각이 눌린다. <b>독립·사업·자영</b>으로 움직일 때 진짜 수입이 열린다 — 월급의 안정감이 오히려 이 팔자의 능력을 잠재운다.`;
386	  if (gwan >= 2 && jae <= 1)
387	    return `관성은 강하고 재성이 약한 구조다. 인정과 직위가 먼저 쌓이고 돈은 그 다음에 따라온다. 빠른 수입을 쫓기보다 <b>전문성·명예·조직 내 지위</b>를 쌓는 방향이 장기적으로 훨씬 큰 결실을 만든다.`;
388	  if (sik >= 2 && jae <= 1 && gwan <= 1)
389	    return `식상이 발달하고 재성·관성이 약한 구조다. <b>재능·기술·표현</b>이 수입원인 팔자다. 남이 만들어 놓은 구조보다 자신만의 방식으로 일할 때 돈이 따라온다 — 프리랜서, 강의, 창작, 서비스에서 가장 자연스럽다.`;
390	  if (in_ >= 2 && jae <= 1)
391	    return `인성이 강한 구조다. 성급하게 수익을 추구할수록 오히려 역효과가 난다. <b>신뢰와 학식</b>이 먼저 쌓이고, 전문성이 깊어질수록 수입이 자연스럽게 따라오는 패턴이다.`;
392	  if (bi >= 2 && jae <= 1)
393	    return `비겁이 강하고 재성이 약한 구조다. 혼자 벌기보다 <b>팀·협업</b>에서 더 큰 수입이 나오는 역설적인 팔자다. 경쟁하기보다 연대하고, 재능 있는 파트너를 곁에 두는 것이 수입의 열쇠다.`;
394	  return `재성·관성·식상이 고르게 분포된 구조다. 여러 경로로 벌 수 있는 팔자이지만, 집중하지 않으면 모든 방향에서 중간치에 머문다 — <b>하나를 깊게 파는 것</b>이 전략이다.`;
395	}
396	
397	export function synthesisNarrative(result) {
398	  if (!result.sajuDetail) return '';
399	  const { axes, strengths, sunSign, fortune, sajuDetail, birthYear } = result;
400	  const CURRENT_YEAR = 2026;
401	  const approxAge = birthYear ? CURRENT_YEAR - birthYear : null;
402	  const dp = sajuDetail.pillars?.dayProfile;
403	  const dayEl = sajuDetail.pillars?.day?.ganEl || '';
404	  const tgs = sajuDetail.tenGodGroups || {};
405	  const natal = fortune?.natal || {};
406	  const timeline = fortune?.timeline || {};
407	
408	  let html = '';
409	
410	  // ① 핵심 정체성 — 조합·역설 중심
411	  const confirmed = axes.filter(a => a.stars >= 3 && a.resultPole !== 0);
412	  const notable   = axes.filter(a => a.stars >= 2 && a.resultPole !== 0);
413	  const conflicts = axes.filter(a => a.conflict);
414	  const coreAxes  = confirmed.length ? confirmed : notable.slice(0, 3);
415	  const topS = [...strengths].sort((a,b) => b.count - a.count).filter(s => s.count >= 3);
416	
417	  html += `<p class="nv-head nv-confirm">🔮 이 사람은 어떤 사람인가</p>`;
418	
419	  // 일간 이미지 + 확정 성향
420	  const elImg = EL_IMAGE[dayEl];
421	  const daySymbol = dp?.symbol || '';
422	  let identLine = elImg
423	    ? `${daySymbol ? `일간 ${daySymbol}, ` : ''}${elImg}처럼 — `
424	    : '';
425	
426	  if (coreAxes.length) {
427	    const poleStr = coreAxes.map(a => `<b>${a.poleLabel}</b>`).join(' · ');
428	    const certainty = confirmed.length >= 2
429	      ? `세 렌즈가 동시에 가리키는 신호, 경향이 아니라 이 사람의 고정된 결이다`
430	      : `여러 렌즈에서 반복 포착되는 패턴이다`;
431	    identLine += `${poleStr}의 성향이 ${certainty}.`;
432	  }
433	  html += `<p>${identLine}</p>`;
434	
435	  // 시스템 간 충돌 → 입체감
436	  if (conflicts.length) {
437	    const cls = conflicts.map(a => a.label).join(' · ');
438	    html += `<p><b>${cls}</b> 영역에서는 시스템마다 신호가 엇갈린다. 이 모순이 결점이 아니다 — 상황에 따라 다른 모습이 나오는, 단순하지 않은 입체적 사람의 증거다.</p>`;
439	  }
440	
441	  // 핵심 강점 (3개 시스템 이상 지목)
442	  if (topS.length) {
443	    html += `<p>세 시스템 이상이 동시에 지목하는 자질 — <b>${topS.map(s => s.name).join(' · ')}</b>. 이 강점이 살아나는 자리에 있을 때 이 사람의 진짜 잠재력이 열린다.</p>`;
444	  }
445	
446	  // 그림자: 일간의 함정
447	  if (dp?.caution) {
448	    const shadow = dp.caution.split(/[.·]/)[0].trim();
449	    if (shadow) html += `<p style="color:var(--muted);font-size:.91rem">그늘 — ${shadow}. 이것이 이 사람이 가장 자주 걸려 넘어지는 함정이다.</p>`;
450	  }
451	
452	  // ② 돈 — 역설과 구체 타이밍
453	  html += `<p class="nv-head">💰 어떻게 돈을 버는 사람인가</p>`;
454	  html += `<p>${incomeParadox(tgs)}</p>`;
455	
456	  const moneyScore = natal.재물 || 50;
457	  const successScore = natal.성공 || 50;
458	  let moneyCtx = moneyScore >= 68
459	    ? `재물 인연이 강한 팔자(${moneyScore}점) — 자산을 다루는 감각이 있고 돈이 비교적 잘 따라온다.`
460	    : moneyScore >= 52
461	    ? `재물운이 중간(${moneyScore}점) — 노력과 타이밍이 결과를 만드는 유형이다. 기회를 알아보는 안목이 관건이다.`
462	    : `재물보다 성취·명예(${successScore}점)가 먼저 오는 팔자(${moneyScore}점) — 인정이 쌓인 뒤 수입이 따라오는 순서다.`;
463	  html += `<p>${moneyCtx}</p>`;
464	
465	  if (timeline.periods?.length > 1) {
466	    const good = timeline.periods.filter(p => p.overall >= 65);
467	    const hard = timeline.periods.filter(p => p.overall < 40);
468	    if (good.length) {
469	      const gs = good.map(p => `<b>${p.startAge}~${p.startAge + 9}세</b>(${p.label})`).join(', ');
470	      html += `<p>기운이 올라오는 구간 ${gs} — 이 시기엔 확장·투자가 결실로 이어진다.</p>`;
471	    }
472	    if (hard.length) {
473	      const hs = hard.map(p => `<b>${p.startAge}~${p.startAge + 9}세</b>`).join(', ');
474	      html += `<p>${hs}는 수축·점검의 시기 — 이때 무리한 도박보다 기반을 조이는 것이 훨씬 현명하다.</p>`;
475	    }
476	  }
477	
478	  // ③ 앞으로 어떻게 될 것인가 — 미니 인생 이야기
479	  html += `<p class="nv-head">🌊 앞으로 어떻게 될 것인가</p>`;
480	
481	  if (approxAge && timeline.periods?.length > 1) {
482	    const sorted = [...timeline.periods].sort((a, b) => a.startAge - b.startAge);
483	    let ci = -1;
484	    for (let i = 0; i < sorted.length; i++) {
485	      const nx = sorted[i + 1];
486	      if (sorted[i].startAge <= approxAge && (!nx || nx.startAge > approxAge)) { ci = i; break; }
487	    }
488	    if (ci >= 0) {
489	      const cur = sorted[ci], nxt = sorted[ci + 1], nxt2 = sorted[ci + 2];
490	
491	      const curMood = cur.overall >= 68
492	        ? `기운이 살아있는 시기다 — 지금 결정한 것이 3년 후의 결과가 된다. 준비보다 실행이 먼저다.`
493	        : cur.overall < 42
494	        ? `기운이 낮은 구간이다. 이 시기의 진짜 과제는 '기다리는 힘'을 기르는 것 — 성급한 결정은 대부분 후회로 돌아온다.`
495	        : `잔잔하게 흐르는 시기다. 파도가 없다는 것은, 지금 쌓는 것이 소리 없이 다음 도약의 기반이 된다는 뜻이다.`;
496	      html += `<p>지금(약 ${approxAge}세)은 <b>${cur.label}</b> 대운 한가운데 — ${curMood}</p>`;
497	
498	      if (nxt) {
499	        const nxtMood = nxt.overall >= 70
