(function() {
  const btns = document.querySelectorAll('button');
  const cardBtns = [...btns].filter(b => b.textContent.trim() === '✦');
  cardBtns[0]?.click(); cardBtns[1]?.click(); cardBtns[2]?.click();
  return `clicked ${cardBtns.length} card buttons`;
})()

(function() {
  const btns = document.querySelectorAll('button');
  const cardBtns = [...btns].filter(b => /카드/.test(b.getAttribute('aria-label') || b.textContent));
  cardBtns[0]?.click(); cardBtns[1]?.click(); cardBtns[2]?.click();
  return `found ${cardBtns.length}, labels: ${cardBtns.slice(0,3).map(b=>b.getAttribute('aria-label')||b.textContent).join(', ')}`;
})()

(function() {
  // Find all buttons and their text/class
  const btns = [...document.querySelectorAll('button')];
  return btns.map(b => ({ text: b.textContent.trim().slice(0,20), cls: b.className.slice(0,30) }));
})()

