(function() {
  const cards = [...document.querySelectorAll('.tcard')];
  if (cards.length >= 3) {
    cards[0].click(); cards[1].click(); cards[2].click();
    return `clicked 3 of ${cards.length} cards`;
  }
  // Check if form panel is still showing
  const tarotBoard = document.querySelector('#tarot-board');
  const form = document.querySelector('form');
  return { cards: cards.length, tarotBoard: !!tarotBoard, form: !!form, html: document.body.innerHTML.slice(0,200) };
})()

(function() {
  // Fill form and submit
  const yearInput = document.querySelector('input[placeholder="년(1990)"]');
  const monthInput = document.querySelector('input[placeholder="월"]');
  const dayInput = document.querySelector('input[placeholder="일"]');
  const mbtiSelect = document.querySelector('select');
  if (yearInput) { yearInput.value = '1990'; yearInput.dispatchEvent(new Event('input', {bubbles:true})); }
  if (monthInput) { monthInput.value = '8'; monthInput.dispatchEvent(new Event('input', {bubbles:true})); }
  if (dayInput) { dayInput.value = '5'; dayInput.dispatchEvent(new Event('input', {bubbles:true})); }
  if (mbtiSelect) { mbtiSelect.value = 'ENFP'; mbtiSelect.dispatchEvent(new Event('change', {bubbles:true})); }

  // Click submit
  const submitBtn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('분석 시작'));
  submitBtn?.click();

  return { submitted: !!submitBtn, year: yearInput?.value, mbti: mbtiSelect?.value };
})()

