input.expression:
(function() {
  const y = document.querySelector('input[placeholder="년(1990)"]');
  const m = document.querySelector('input[placeholder="월"]');
  const d = document.querySelector('input[placeholder="일"]');
  const mbti = document.querySelector('select');
  if (y) { y.value='1990'; y.dispatchEvent(new Event('input',{bubbles:true})); }
  if (m) { m.value='8'; m.dispatchEvent(new Event('input',{bubbles:true})); }
  if (d) { d.value='5'; d.dispatchEvent(new Event('input',{bubbles:true})); }
  if (mbti) { mbti.value='ENFP'; mbti.dispatchEvent(new Event('change',{bubbles:true})); }
  const btn = [...document.querySelectorAll('button')].find(b=>b.textContent.includes('분석 시작'));
  btn?.click();
  return 'submitted';
})()

(function() {
  const cards = [...document.querySelectorAll('.tcard')];
  if (cards.length >= 3) { cards[0].click(); cards[2].click(); cards[5].click(); return 'cards clicked'; }
  return { cards: cards.length };
})()

(function() {
  const yf = document.querySelector('.yf-card');
  if (!yf) return 'yf-card NOT found';
  yf.scrollIntoView({ behavior: 'instant' });
  return { found: true, html: yf.innerHTML.slice(0, 600) };
})()

