function sajuMbtiCross(dayEl, mbti) {
  if (!dayEl || !mbti || mbti.length < 4) return null;
  const ie = mbti[0] === 'I' ? 'I' : 'E';
  const tf = mbti[2] === 'T' ? 'T' : 'F';
  return SAJU_MBTI_CROSS[`${dayEl}_${ie}${tf}`] || null;
}

