694	export function timeNarrative(spread) {
695	  if (!spread || !spread.length) return '';
696	  let html = '';
697	  spread.forEach(s => {
698	    const long = TAROT_LONG[s.card.id] || { up: s.card.upright, down: s.card.reversed };
699	    const body = s.reversed ? long.down : long.up;
700	    const orient = s.reversed ? '역방향' : '정방향';
701	    html += `<p><b>${s.position} · ${s.card.emoji} ${s.card.name} (${orient})</b><br>${POS_FRAME[s.position] || ''}${body}</p>`;
702	  });
703	  html += '<p class="nv-foot">기억하자 — 타로의 미래는 정해진 운명이 아니라, 지금 너의 선택으로 얼마든지 다시 쓸 수 있는 가능성의 지도다.</p>';
704	  return html;
705	}
