      '나를 바르게 길러 주는 기운, 정인이 들어오는 따뜻한 해다. 좋은 스승과 귀인의 도움이 닿고, 배우고 익힌 것이 차곡차곡 실력으로 쌓이며, 마음의 안정과 명예가 함께 따라오는 시기다. ' +
      '서두르기보다 한 박자 쉬어 가며 내면을 채우는 것이 오히려 다음 도약을 위한 가장 좋은 준비가 되는 한 해다. ' +
      '받은 것을 겸손히 받아들이고 배움을 게을리하지 않으면, 올해 만난 인연과 지식이 두고두고 든든한 자산으로 남는다.',
    money: '재물을 좇기보다 신뢰와 학식을 쌓을 때 수입이 자연히 따라온다. 무리한 투자보다 안정과 저축이 어울리는 해다.',
    work: '배움과 자기계발이 큰 힘이 된다. 자격·학위·전문성을 쌓거나, 좋은 멘토 아래서 성장하기에 더없이 좋은 시기다.',
    relation: '귀인과 윗사람의 도움이 닿는다. 특히 어머니·스승 같은 손위 인연이 삶의 든든한 버팀목이 되어 준다.',
    health: '심신이 안정되는 편안한 해다. 충분한 휴식과 회복에 좋은 때이니, 무리했던 몸을 돌보기에 알맞다.',
    yearlyAdvice: '쉬어 가는 것을 두려워 말라. 올해의 배움과 회복은 멈춤이 아니라, 더 높이 오르기 위해 숨을 고르는 시간이다.',
    daily:
      '도움의 손길이 닿거나 배울 기회가 열리는 날이다. 마음이 차분히 가라앉아 무리 없이 흘러가는 하루다. ' +
      '겸손하게 받아들이는 태도를 지니면, 뜻밖의 지혜나 누군가의 따뜻한 지원이 자연스럽게 다가온다.',
  },
};

function pillarFromDate(year, month, day) {
  try {
    const ec = Solar.fromYmd(year, month, day).getLunar().getEightChar();
    return {
      yearGan: ec.getYearGan(), yearZhi: ec.getYearZhi(),
      monthGan: ec.getMonthGan(), dayGan: ec.getDayGan(), dayZhi: ec.getDayZhi(),
    };
  } catch { return null; }
}

function pad2(n) { return String(n).padStart(2, '0'); }

// 그 해의 '기후' 한 문장 — 천간·지지 오행으로 한 해 바탕 기운을 묘사
function yearClimate(gan, zhi, animal) {
  const ge = GAN_EL[gan], ze = ZHI_EL[zhi];
  if (!ge || !ze) return '';
  if (ge === ze) {
    return `<b>${animal}의 해</b>인 올해는 ${ge}(五行)의 기운이 두 겹으로 짙게 흐른다 — ${EL_CLIMATE[ge]}이 한 해 전체에 강하게 깔린다.`;
  }
  return `<b>${animal}의 해</b>인 올해는 천간 ${ge}·지지 ${ze}의 기운이 함께 흐른다 — ${EL_CLIMATE[ge]} 위로 ${EL_CLIMATE[ze]}이 더해지는 결이다.`;
}

function aspects(f) {
  return [
    { icon: '💰', label: '재물', text: f.money },
    { icon: '💼', label: '일·커리어', text: f.work },
    { icon: '❤️', label: '관계', text: f.relation },
    { icon: '🌿', label: '건강', text: f.health },
  ];
}

export function analyzeYearlyFortune(birth) {
  try {
    const userPillar = pillarFromDate(birth.year, birth.month, birth.day);
    if (!userPillar) return null;
    const dayGan = userPillar.dayGan;

    const now = new Date();
    const cy = now.getFullYear(), cm = now.getMonth() + 1, cd = now.getDate();

    const todayP = pillarFromDate(cy, cm, cd);
    const nyP = pillarFromDate(cy + 1, 1, 15);
    if (!todayP) return null;

    const todayDayTG  = tenGod(dayGan, todayP.dayGan);
    const todayMonTG  = tenGod(dayGan, todayP.monthGan);
    const thisYearTG  = tenGod(dayGan, todayP.yearGan);
    const nextYearTG  = nyP ? tenGod(dayGan, nyP.yearGan) : null;

    const dayF  = TG_FORTUNE[todayDayTG]  || TG_FORTUNE['비견'];
    const tyF   = TG_FORTUNE[thisYearTG]  || TG_FORTUNE['비견'];
    const nyF   = nextYearTG ? (TG_FORTUNE[nextYearTG] || TG_FORTUNE['비견']) : null;

    const monMod = (TG_FORTUNE[todayMonTG]?.score || 60) >= 68 ? 4 : -3;
    const todayScore = Math.min(95, Math.max(30, dayF.score + monMod));

    const tyAnimal = ZHI_ANIMAL[todayP.yearZhi] || '';
    const nyAnimal = nyP ? (ZHI_ANIMAL[nyP.yearZhi] || '') : '';

    return {
      dayGan,
      today: {
        dateStr: `${cy}.${pad2(cm)}.${pad2(cd)}`,
        gan: todayP.dayGan, zhi: todayP.dayZhi,
        tenGod: todayDayTG, score: todayScore,
        label: dayF.label,
        flow: dayF.daily,
        aspects: null,
        advice: null,
      },
      thisYear: {
        year: cy, gan: todayP.yearGan, zhi: todayP.yearZhi, animal: tyAnimal,
        tenGod: thisYearTG, score: tyF.score, label: tyF.label,
        climate: yearClimate(todayP.yearGan, todayP.yearZhi, tyAnimal),
        flow: tyF.yearlyFlow,
        aspects: aspects(tyF),
        advice: tyF.yearlyAdvice,
      },
      nextYear: nyP ? {
        year: cy + 1, gan: nyP.yearGan, zhi: nyP.yearZhi, animal: nyAnimal,
        tenGod: nextYearTG, score: nyF?.score || 60, label: nyF?.label || nextYearTG,
        climate: yearClimate(nyP.yearGan, nyP.yearZhi, nyAnimal),
        flow: nyF?.yearlyFlow || '',
        aspects: nyF ? aspects(nyF) : null,
        advice: nyF?.yearlyAdvice || null,
      } : null,
    };
  } catch { return null; }
}

toolUseResult.content:
import { Solar } from 'lunar-javascript';
import { tenGod } from './fortune.js';

const ZHI_ANIMAL = { '子':'쥐','丑':'소','寅':'호랑이','卯':'토끼','辰':'용','巳':'뱀','午':'말','未':'양','申':'원숭이','酉':'닭','戌':'개','亥':'돼지' };

const GAN_EL = { '甲':'목','乙':'목','丙':'화','丁':'화','戊':'토','己':'토','庚':'금','辛':'금','壬':'수','癸':'수' };
const ZHI_EL = { '子':'수','丑':'토','寅':'목','卯':'목','辰':'토','巳':'화','午':'화','未':'토','申':'금','酉':'금','戌':'토','亥':'수' };

// 오행별 그 해의 '기후' — 한 해 전체에 깔리는 바탕 기운
const EL_CLIMATE = {
  목: '새싹이 흙을 뚫고 올라오듯, 무언가를 새로 시작하고 위로 뻗어나가려는 성장의 기운',
  화: '불꽃이 사방으로 번지듯, 밖으로 드러나고 넓게 확장하려는 열정과 표현의 기운',
  토: '땅을 단단히 다지듯, 중심을 잡고 안정시키며 쌓아 올리는 현실의 기운',
  금: '가을걷이처럼 거두고 정리하며 결실을 매듭짓는, 단호하고 명료한 기운',
  수: '물이 낮은 곳으로 모이듯, 안으로 거두어 깊이 사유하고 다음을 준비하는 지혜의 기운',
