  document.querySelector('select[id*="mbti" i], #mbti')?.value;
  // MBTI select 찾기
  const selects = [...document.querySelectorAll('select')];
  const mbtiSel = selects.find(s => [...s.options].some(o => o.value === 'ENFP'));
  if (mbtiSel) { mbtiSel.value = 'ENFP'; mbtiSel.dispatchEvent(new Event('change', {bubbles:true})); }
  // 월/일 채우기 (혹시 비었으면)
  const nums = [...document.querySelectorAll('input[type=number]')];
  if (nums[1] && !nums[1].value) nums[1].value = '5';
  if (nums[2] && !nums[2].value) nums[2].value = '15';
  // 시간 모름 체크
  return { mbti: mbtiSel?.value, nums: nums.map(n=>n.value) };
})()

(() => {
  const nums = [...document.querySelectorAll('.view.active input[type=number], #profile input[type=number]')].length
    ? [...document.querySelectorAll('.view.active input[type=number]')]
    : [...document.querySelectorAll('input[type=number]')];
  nums[0].value = '1990'; nums[0].dispatchEvent(new Event('input',{bubbles:true}));
  nums[1].value = '5'; nums[1].dispatchEvent(new Event('input',{bubbles:true}));
  nums[2].value = '15'; nums[2].dispatchEvent(new Event('input',{bubbles:true}));
  // 시간 모름 체크
  const cb = [...document.querySelectorAll('input[type=checkbox]')].find(c => /시간/.test(c.parentElement?.textContent||''));
  if (cb && !cb.checked) { cb.checked = true; cb.dispatchEvent(new Event('change',{bubbles:true})); }
  return { y: nums[0].value, m: nums[1].value, d: nums[2].value, timeUnknown: cb?.checked };
})()

(() => {
  const btn = [...document.querySelectorAll('button')].find(b => /분석 시작/.test(b.textContent));
