149	export function getSajuPillars(birth) {
150	  const { year, month, day, hour, calendar } = birth;
151	  const timeUnknown = hour == null;
152	  const h = timeUnknown ? 12 : hour;
153	  const solar = calendar === 'lunar'
154	    ? Lunar.fromYmdHms(year, month, day, h, 0, 0).getSolar()
155	    : Solar.fromYmdHms(year, month, day, h, 0, 0);
156	  const ec = solar.getLunar().getEightChar();
157	
158	  const yg = ec.getYearGan(), yz = ec.getYearZhi();
159	  const mg = ec.getMonthGan(), mz = ec.getMonthZhi();
160	  const dg = ec.getDayGan(), dz = ec.getDayZhi();
161	  const tg = timeUnknown ? null : ec.getTimeGan();
162	  const tz = timeUnknown ? null : ec.getTimeZhi();
163	
164	  return {
165	    year:  makePillar(yg, yz),
166	    month: makePillar(mg, mz),
167	    day:   makePillar(dg, dz),
168	    time:  tg ? makePillar(tg, tz) : null,
169	    dayGan: dg,
170	    dayProfile: DAY_GAN_PROFILE[dg] || null,
171	    timeUnknown,
172	  };
173	}
