175	export function getOhaengBalance(pillars) {
176	  const counts = { 목:0, 화:0, 토:0, 금:0, 수:0 };
177	  const add = el => { if (el && counts[el] !== undefined) counts[el]++; };
178	  [pillars.year, pillars.month, pillars.day, pillars.time].filter(Boolean).forEach(p => {
179	    add(p.ganEl); add(p.zhiEl);
180	  });
181	  return counts;
182	}
