import { Solar, Lunar } from 'lunar-javascript';

const GAN_ELEMENT = { '甲':'목','乙':'목','丙':'화','丁':'화','戊':'토','己':'토','庚':'금','辛':'금','壬':'수','癸':'수' };
const ZHI_ELEMENT = { '子':'수','丑':'토','寅':'목','卯':'목','辰':'토','巳':'화','午':'화','未':'토','申':'금','酉':'금','戌':'토','亥':'수' };
const GAN_KO = { '甲':'갑','乙':'을','丙':'병','丁':'정','戊':'무','己':'기','庚':'경','辛':'신','壬':'임','癸':'계' };
const ZHI_KO = { '子':'자','丑':'축','寅':'인','卯':'묘','辰':'진','巳':'사','午':'오','未':'미','申':'신','酉':'유','戌':'술','亥':'해' };
const ZHI_ANIMAL = { '子':'쥐','丑':'소','寅':'호랑이','卯':'토끼','辰':'용','巳':'뱀','午':'말','未':'양','申':'원숭이','酉':'닭','戌':'개','亥':'돼지' };

export const OHAENG_COLOR = { 목:'#4caf50', 화:'#e53935', 토:'#ff9800', 금:'#9e9e9e', 수:'#2196f3' };

export const DAY_GAN_PROFILE = {
  '甲': {
    symbol:'큰 나무(大木)', element:'목(木)', core:'독립·성장·선구',
    text:'하늘을 향해 곧게 뻗는 큰 나무의 기운이다. 뚜렷한 목표의식과 선구자적 기질이 있으며, 한번 방향을 정하면 굽히지 않는 추진력이 있다. 남의 지시보다 스스로 길을 개척하는 자리에서 진가가 드러난다.',
    talent:'아무도 가지 않은 길을 처음 내는 기획력과 추진력이 타고난 재능이다. 큰 그림을 그리고 첫 발을 내딛는 데 두려움이 없으며, 사람들을 앞에서 이끄는 리더십이 자연스럽다. 새로운 분야를 개척하거나 조직을 처음 세우는 일에서 천부적인 능력이 드러난다.',
    careers:['창업가·기업인','기획자·전략가','정치인·공무원','감독·연출가','건축가','군인·경찰관','스포츠 선수·코치','개발자·엔지니어'],
    fate:'개척자형 팔자다. 초년엔 거친 길을 혼자 걸어야 하는 시간이 길지만, 그 과정이 곧 자산이 된다. 중년 이후 자신만의 무대를 완성하며 인정을 받는 경우가 많다. 일찍 성공보다 꾸준히 쌓는 쪽이 더 오래 빛난다.',
    weakness:'고집으로 인한 독선이 가장 큰 맹점이다. 한번 방향을 정하면 타인의 조언을 흘려듣고, 타협 자체를 약함으로 느낀다. 조급하게 밀어붙이다 중요한 신호를 놓치는 실수를 반복하는 경향이 있다.',
    caution:'과욕과 조급함이 가장 큰 적이다. 밀어붙이는 시기에 오히려 멈춰야 할 때를 놓치기 쉽고, 무리한 확장과 독단적 결정이 기반을 흔든다. 나무를 쪼개는 금(金)의 기운이 강한 해·시기엔 건강과 사고에 특히 주의할 것.',
  },
  '乙': {
    symbol:'덩굴·꽃(草木)', element:'목(木)', core:'유연·관계·적응',
    text:'유연하게 뻗어나가는 덩굴풀과 꽃의 기운이다. 환경에 탁월하게 적응하고 사람들 사이에서 조화를 이끌어내는 능력이 뛰어나다. 겉은 부드러우나 안은 단단하며, 억지로 밀기보다 스며드는 방식으로 원하는 것을 이루는 유형이다.',
    talent:'타인의 감정과 분위기를 읽는 섬세한 공감 능력이 타고난 재능이다. 낯선 환경에서도 빠르게 관계망을 형성하고, 갈등 상황에서 자연스럽게 중재자 역할을 한다. 심미안도 뛰어나 색·공간·언어에서 독특한 감각이 있다.',
    careers:['상담사·코치','외교관·통역가','HR·채용 전문가','영업·마케터','디자이너·플로리스트','간호사·의료인','교사·강사','이벤트 기획자'],
    fate:'관계형 팔자다. 혼자보다 함께할 때 비로소 빛이 난다. 좋은 파트너나 멘토를 만나느냐가 운명의 갈림길이 되며, 인간관계 속에서 자연스럽게 성장한다. 중년 이후 안정된 네트워크가 탄탄한 기반이 된다.',
    weakness:'우유부단함과 지나친 눈치가 가장 큰 맹점이다. 자기주장이 약해 원하는 것을 말하지 못하고 뒤에서 불만을 쌓는 경향이 있다. 타인 의존도가 높아 관계가 흔들릴 때 함께 흔들린다.',
    caution:'타인에게 지나치게 맞추다 정작 자신을 잃는 것이 최대 함정이다. 감정에 휩쓸려 중요한 결정을 미루거나, 잘못된 관계에 오래 매여 있으면 기회를 놓친다. 금(金)의 기운이 강한 시기엔 관계 정리와 자기주장 연습이 필요하다.',
  },
  '丙': {
    symbol:'태양(太陽)', element:'화(火)', core:'열정·카리스마·표현',
    text:'세상을 환하게 비추는 태양의 기운이다. 밝고 따뜻한 에너지로 주변을 끌어당기며, 어디서나 존재감이 뚜렷하다. 표현이 직접적이고 열정이 강하며, 사람들에게 희망과 활력을 불어넣는 역할을 자연스럽게 맡는다.',
    talent:'군중을 움직이는 카리스마와 강렬한 표현력이 타고난 재능이다. 무대 위에서 자연스럽게 에너지를 발산하고, 말과 행동으로 사람들의 마음에 불을 지피는 능력이 있다. 설득력과 영향력이 타고나 있어, 큰 청중 앞에서 오히려 더 빛난다.',
    careers:['연예인·방송인','강사·강연가','영업·마케터','정치인','이벤트·파티 기획자','코치·멘토','광고·홍보 전문가','스포츠 선수'],
    fate:'빛발형 팔자다. 무대가 있어야 산다. 주목받는 자리에서 꽃을 피우며, 사람들에게 에너지를 주는 역할로 성공한다. 초년의 인기, 중년의 기복, 말년에 남는 명성의 흐름이 많다. 빛나는 만큼 그늘도 생기는 것을 이해해야 한다.',
    weakness:'지속성 부족과 마무리 약함이 가장 큰 맹점이다. 불꽃처럼 강렬하게 시작하지만 타오르고 나면 식는다. 자기중심적인 면이 있어 타인의 감정을 놓치고, 과시욕이 실속보다 이미지를 앞서게 만든다.',
    caution:'빛나는 이미지 뒤에 실속이 없으면 오래 버티지 못한다. 과시와 허영이 방향을 잃게 하는 함정이다. 물(水)의 기운이 강한 시기엔 체력·감정 소진과 인간관계 균열에 각별히 주의할 것.',
  },
  '丁': {
    symbol:'촛불·달(月火)', element:'화(火)', core:'집중·섬세·내공',
    text:'어둠 속 촛불처럼 집중된 빛을 발하는 기운이다. 예민하고 섬세한 내면의 불꽃을 품고 있으며, 겉은 조용해도 안에서 강렬하게 타오른다. 한 분야에 깊이 파고드는 집중력이 뛰어나고, 화려함보다 깊이로 승부하는 유형이다.',
    talent:'한 분야를 끝까지 파고드는 집중력과 섬세한 탐구 능력이 타고난 재능이다. 언어와 표현의 정밀함이 있어 복잡한 것을 명확하게 전달하는 데 능하다. 예민한 미적 감각과 심층적 사유력으로 남들이 보지 못하는 것을 발견한다.',
    careers:['연구자·과학자','예술가·음악가','작가·시인','의사·한의사·치료사','교사·교수','상담사·심리사','엔지니어·기술자','정밀 기술직'],
    fate:'탐구형 팔자다. 한 분야의 전문가로 자신만의 세계를 쌓아가는 유형이다. 겉으로는 조용하지만 내면에서 치열하게 타오른다. 인정받는 데 시간이 걸리지만, 전문성이 쌓이면 흔들리지 않는 위치에 선다.',
    weakness:'번아웃에 취약하고, 과민반응으로 인한 감정 기복이 맹점이다. 완벽주의가 지나쳐 시작 자체를 두려워하거나, 혼자 안에서 다 태우다 소진되는 패턴을 반복한다. 주변과 단절하고 자기 세계에만 갇히는 경향도 있다.',
    caution:'번아웃이 최대 적이다. 혼자 감당하며 주변과 단절하면 기회를 놓친다. 감정 기복이 심한 시기엔 중요한 결정을 보류하는 것이 좋다. 물(水)의 기운이 강한 시기엔 감정 건강과 체력 관리를 최우선으로 해야 한다.',
  },
  '戊': {
    symbol:'큰 산(大山)', element:'토(土)', core:'안정·신뢰·중심',
    text:'흔들리지 않는 큰 산의 기운이다. 묵직한 존재감과 신뢰감으로 주변에 안정을 준다. 결코 서두르지 않으며 오랜 시간 한 자리를 지키는 인내심을 가졌다. 책임감이 강하고 의리를 중시하며, 조직 안에서 중심을 잡는 역할을 자주 맡는다.',
    talent:'흔들리지 않는 안정감과 신뢰를 주는 능력이 타고난 재능이다. 조직과 사람들을 오랜 시간 묵묵히 지지하며, 위기 상황에서도 중심을 잡는 능력이 탁월하다. 장기적인 관점에서 일을 설계하고 관리하는 감각이 뛰어나다.',
    careers:['공무원·행정직','군인·경찰관','금융·보험 전문가','건설·부동산업','경영관리자','의료인','농업·식품업','조직 내 관리자·임원'],
    fate:'기둥형 팔자다. 조직과 가정의 중심이 되는 안정 지향형이다. 빠른 성공보다 오랜 신뢰로 쌓아 올리며, 중년 이후 탄탄한 기반이 완성된다. 느리게 가더라도 흔들리지 않는 힘이 결국 이긴다.',
    weakness:'변화에 둔감하고 새로운 시도를 회피하는 것이 가장 큰 맹점이다. 너무 오래 같은 자리에 머물다 시대 변화를 놓치거나, 고집으로 인해 주변과 갈등이 생기는 패턴이 있다.',
    caution:'변화가 필요한 시기에 변화를 거부하다 정체되는 것이 최대 위험이다. 나무(木)의 기운이 강한 시기엔 건강·재물·관재 문제에 주의하고, 단단함 속에 유연함을 더하는 연습이 필요하다.',
  },
  '己': {
    symbol:'논밭·대지(田土)', element:'토(土)', core:'세심·배려·현실',
    text:'만물을 기르는 논밭 같은 기운이다. 꼼꼼하고 세심하게 상황을 살피며, 현실적인 방식으로 문제를 해결한다. 배려심이 깊어 남의 필요를 먼저 채우려 하며, 주변을 풍성하게 만드는 능력이 있다.',
    talent:'사람을 돌보고 기르는 능력이 타고난 재능이다. 꼼꼼한 실무 처리 능력과 배려 기반의 신뢰 구축이 강점으로, 타인이 필요한 것을 남들보다 먼저 알아차린다. 현실적인 감각으로 복잡한 상황을 차분하게 정리한다.',
    careers:['교사·유아교육','의료·간호·요양보호','사회복지사','영양사·요리사','회계·행정직','상담사','코디네이터','조리·식품업'],
    fate:'지지형 팔자다. 뒤에서 세상을 떠받치는 조용한 힘이다. 중심보다 조력자 역할로 빛나며, 진심이 쌓여야 인정이 따라온다. 인내의 시간이 길지만 결국 주변의 신뢰와 감사가 자산이 된다.',
    weakness:'자기희생이 지나쳐 스스로를 소진하는 것이 가장 큰 맹점이다. 우유부단하고 자기표현이 약해 손해를 먼저 감수하는 패턴을 반복한다. 타인을 위해 헌신하지만 정작 자신의 욕구는 오래 억누른다.',
    caution:'자기 소모가 최대 위험이다. 남을 위해 자신을 다 내어주면 정작 자신이 빈껍데기가 된다. 나무(木)의 기운이 강한 시기엔 건강 소홀, 금전·소송 문제에 주의하고, 자신의 경계를 지키는 연습이 필요하다.',
  },
  '庚': {
    symbol:'도끼·원석(金石)', element:'금(金)', core:'결단·강직·원칙',
    text:'원석을 깎아내는 도끼의 기운이다. 원칙과 기준이 뚜렷하며 일 처리가 빠르고 과감하다. 옳고 그름에 대한 판단이 명확해 불의를 참지 못한다. 강한 의지와 실행력으로 어려운 일도 밀어붙이는 추진력이 있다.',
    talent:'흔들리지 않는 결단력과 어떤 어려움도 밀어붙이는 실행력이 타고난 재능이다. 원칙을 지키며 공정하게 처리하는 능력이 있고, 위기 상황일수록 오히려 더 냉정하게 판단한다. 복잡한 것을 단번에 정리하는 칼날 같은 결정력이 있다.',
    careers:['군인·경찰관','검사·판사·법률가','외과의사·치과의사','엔지니어·기계기술자','CEO·경영자','운동선수·격투기','금속·제조업','IT·시스템 관리'],
    fate:'전사형 팔자다. 인생에 굵직한 도전이 많지만 그 과정에서 단련되어 더욱 단단해진다. 조직보다 자신의 원칙이 먼저인 유형이라, 독자적인 분야에서 더 빛난다. 정점에 오르는 길이 험하지만 오르고 나면 쉽게 흔들리지 않는다.',
    weakness:'지나친 강직함이 관계와 기회를 끊는 것이 가장 큰 맹점이다. 타협을 약함으로 보고, 감정 표현이 서툴러 주변 사람들이 벽을 느낀다. 독단적인 결정으로 팀이 무너지거나 갈등이 깊어지는 경우가 있다.',
    caution:'강직함이 고집이 되는 순간 관계가 끊긴다. 불(火)의 기운이 강한 시기엔 과로·사고·다툼에 주의해야 하며, 유연함을 의식적으로 연습하지 않으면 고립될 수 있다.',
  },
