(() => {
  const selects = [...document.querySelectorAll('select')];
  const mbtiSel = selects.find(s => [...s.options].some(o => o.value === 'ENFP'));
  if (mbtiSel) { mbtiSel.value='ISTJ'; mbtiSel.dispatchEvent(new Event('change',{bubbles:true})); }
  const nums = [...document.querySelectorAll('input[type=number]')];
  const set=(i,v)=>{nums[i].value=v;nums[i].dispatchEvent(new Event('input',{bubbles:true}));};
  set(0,'1985'); set(1,'12'); set(2,'3'); set(3,'9');
  const f=[...document.querySelectorAll('input[name=gender]')].find(r=>/여/.test(r.parentElement?.textContent||''));
  if(f){f.checked=true;f.dispatchEvent(new Event('change',{bubbles:true}));}
  [...document.querySelectorAll('button')].find(b=>/분석 시작/.test(b.textContent))?.click();
  setTimeout(()=>{const c=[...document.querySelectorAll('.tcard.back')];c[1]?.click();c[5]?.click();c[9]?.click();},150);
  return 'ok';
})()

(() => {
  const cards=[...document.querySelectorAll('.report .card')];
  const order=cards.map(c=>c.querySelector('h3')?.innerText?.split('\n')[0]).filter(Boolean);
  const sum=document.querySelector('.summary-card');
  return {
    order: order.slice(0,6),
    summaryFirst: order[0],
    sumIdent: sum?.querySelector('.sum-ident')?.innerText,
    chips: [...(sum?.querySelectorAll('.sum-chip')||[])].map(c=>c.innerText),
    core: sum?.querySelector('.sum-core')?.innerText,
    summaryAtTop: cards[0]?.classList.contains('summary-card'),
  };
})()

(() => {
  const c=document.querySelector('.summary-card');
  return {
    bg: getComputedStyle(c).backgroundImage.slice(0,30),
    coreBg: getComputedStyle(c.querySelector('.sum-core')).backgroundColor,
    rowCols: getComputedStyle(c.querySelector('.sum-row')).gridTemplateColumns,
    guide: c.querySelector('.sum-guide')?.innerText,
  };
})()

