1	import { Solar, Lunar } from 'lunar-javascript';
2	
3	// 천간 → 오행/음양
4	const GAN_INFO = {
5	  甲:{e:'목',yin:false}, 乙:{e:'목',yin:true}, 丙:{e:'화',yin:false}, 丁:{e:'화',yin:true},
6	  戊:{e:'토',yin:false}, 己:{e:'토',yin:true}, 庚:{e:'금',yin:false}, 辛:{e:'금',yin:true},
7	  壬:{e:'수',yin:false}, 癸:{e:'수',yin:true},
8	};
9	const SHENG = { 목:'화', 화:'토', 토:'금', 금:'수', 수:'목' };
10	const KE = { 목:'토', 토:'수', 수:'화', 화:'금', 금:'목' };
11	
12	const clamp = (n, lo = 18, hi = 96) => Math.max(lo, Math.min(hi, Math.round(n)));
13	
14	// 일간 기준 다른 천간의 십성
15	export function tenGod(dayGan, other) {
16	  const d = GAN_INFO[dayGan], o = GAN_INFO[other];
17	  if (!d || !o) return null;
18	  const same = d.yin === o.yin;
19	  if (d.e === o.e) return same ? '비견' : '겁재';
20	  if (SHENG[d.e] === o.e) return same ? '식신' : '상관';
21	  if (KE[d.e] === o.e) return same ? '편재' : '정재';
22	  if (KE[o.e] === d.e) return same ? '편관' : '정관';
23	  if (SHENG[o.e] === d.e) return same ? '편인' : '정인';
24	  return '비견';
25	}
26	
27	// 사주 본명(natal) 십성 카운트 → 가족 인연 점수 (성별 반영)
28	export function relationFortune(counts, gender) {
29	  const c = k => counts[k] || 0;
30	  const isFemale = gender === 'female';
31	
32	  // 배우자성: 남=재성(정재+편재), 여=관성(정관+편관); 상관은 관성을 극해 여성 배우자운 손상
33	  const spouse = isFemale
34	    ? clamp(42 + c('정관') * 12 + c('편관') * 7 - c('상관') * 5)
35	    : clamp(42 + c('정재') * 12 + c('편재') * 7 - c('겁재') * 3);
36	
37	  // 자식성: 남=관성, 여=식상
38	  const child = isFemale
39	    ? clamp(42 + c('식신') * 14 + c('상관') * 7)
40	    : clamp(42 + c('정관') * 12 + c('편관') * 8);
41	
42	  // 부모: 인성=어머니, 재성(편재)=아버지
43	  const parent = clamp(45 + c('정인') * 12 + c('편인') * 5 + c('편재') * 8 + c('정재') * 4);
44	
45	  // 형제: 비견=형제, 겁재=경쟁형 형제(2개 이상이면 갈등)
46	  const sibling = clamp(42 + c('비견') * 14 + c('겁재') * 3 - Math.max(0, c('겁재') - 1) * 5);
47	
48	  return { 배우자: spouse, 자식: child, 부모: parent, 형제: sibling };
49	}
50	
51	// 사주 본명(natal) 십성 카운트 → 4대 운 점수
52	export function natalFortune(counts) {
53	  const c = k => counts[k] || 0;
54	  return {
55	    재물: clamp(40 + c('정재') * 14 + c('편재') * 10 + (c('식신') + c('상관')) * 4),
56	    성공: clamp(40 + c('정관') * 14 + c('편관') * 8 + (c('정인') + c('편인')) * 5),
57	    연애: clamp(42 + (c('정재') + c('편재')) * 8 + (c('식신') + c('상관')) * 8 + (c('정관') + c('편관')) * 4),
58	    건강: clamp(55 + (c('정인') + c('편인')) * 8 + (c('비견') + c('겁재')) * 5 - c('편관') * 6),
59	  };
60	}
61	
62	// 대운 천간 십성 → 그 시기 종합 운세 가중
63	const TENGOD_FORTUNE = {
64	  정관: 16, 정재: 14, 편재: 12, 식신: 10, 정인: 8, 편인: 2,
65	  비견: 2, 상관: -2, 겁재: -8, 편관: -12,
66	};
67	
68	const TENGOD_LABEL = {
69	  정관: '명예·직장운', 편관: '시련·압박', 정재: '재물운', 편재: '활동·투자운',
70	  식신: '표현·여유', 상관: '변화·구설', 정인: '학업·안정', 편인: '재능·고독',
71	  비견: '협력·경쟁', 겁재: '경쟁·지출',
72	};
73	
74	// 대운 타임라인. birth: { year, month, day, hour, calendar, gender }
75	export function lifeTimeline(birth) {
76	  try {
77	    const { year, month, day, hour, calendar, gender } = birth;
78	    const h = hour == null ? 12 : hour;
