};

// 일간 오행 기준으로 다른 오행이 아군(돕는)인지 적군(빼는)인지
function relationToDay(dayEl, el) {
  if (el === dayEl) return '비겁';
  if (el === genOf(dayEl)) return '인성';
  if (el === SHENG[dayEl]) return '식상';
  if (el === KE[dayEl]) return '재성';
