    if (rel === '비겁' || rel === '인성') supportW += w;
    else drainW += w;
  });
  const total = supportW + drainW || 1;
  const strongPct = Math.round(supportW / total * 100);

  // 월령(月令) 득령 여부 — 월지 정기로 판정
  const monthMainGan = (ZHI_HIDDEN[p.month?.zhi] || [])[0];
