import { tenGod } from './fortune.js';

// 월지 지장간 — [정기, 중기, 여기]
const ZHI_HIDDEN = {
  '子':['癸'], '丑':['己','癸','辛'], '寅':['甲','丙','戊'], '卯':['乙'],
  '辰':['戊','乙','癸'], '巳':['丙','庚','戊'], '午':['丁','己'], '未':['己','丁','乙'],
  '申':['庚','壬','戊'], '酉':['辛'], '戌':['戊','辛','丁'], '亥':['壬','甲'],
};

// 격국 정의 — 십신(월지 격 기준) → 격
const GYEOK = {
  정관: {
    name: '정관격', hanja: '正官格', type: '길격',
    desc: '법과 질서, 명예를 중시하는 모범생형 그릇이다. 책임 있는 자리에서 인정받으며, 조직·공직·관리·행정에서 크게 쓰인다. 원칙을 지키는 반듯함이 평생의 무기다.',
    sangsin: '재성(財生官)이 관을 살리고 인성(官印相生)이 받쳐줄 때 격이 완성된다.',
  },
  편관: {
    name: '칠살격', hanja: '七殺格(偏官格)', type: '제화 필요',
    desc: '칼 같은 카리스마와 결단의 그릇이다. 잘 다스리면 큰 권력·무관·전문직으로 우뚝 서고, 못 다스리면 압박과 시련에 휘둘린다. 위기에서 오히려 강해지는 유형.',
    sangsin: '식신으로 살을 제압(食神制殺)하거나 인성으로 살을 돌리면(殺印相生) 큰 인물이 된다.',
  },
  정재: {
    name: '정재격', hanja: '正財格', type: '길격',
    desc: '성실하게 벌어 착실히 쌓는 실속형 그릇이다. 정당한 노력과 신용으로 부를 이루며, 안정적인 생활과 가정을 중시한다. 한 방보다 꾸준함으로 이긴다.',
    sangsin: '식상이 재를 낳고(食傷生財), 일간이 강해 그 재물을 감당할 때 격이 완성된다.',
