      else good = '식신을 빼앗는 편인이 없어 복록이 온전한 구조다.';
      break;
    case '편인':
      if (c('식신')) warn = '식신을 보면 효신탈식(梟神奪食)으로 복이 새기 쉽다 — 재성으로 편인을 눌러주는 것이 관건이다.';
      break;
    case '정인':
      if (c('편재') + c('정재') >= 2) warn = '재성(財星)이 왕성해 인을 깨니(財剋印) 학업·명예·문서가 흔들리기 쉽다 — 재물 욕심을 절제해야 격이 산다.';
