import { tenGod } from './fortune.js';

// 월지 지장간 — [정기, 중기, 여기]
const ZHI_HIDDEN = {
  '子':['癸'], '丑':['己','癸','辛'], '寅':['甲','丙','戊'], '卯':['乙'],
  '辰':['戊','乙','癸'], '巳':['丙','庚','戊'], '午':['丁','己'], '未':['己','丁','乙'],
  '申':['庚','壬','戊'], '酉':['辛'], '戌':['戊','辛','丁'], '亥':['壬','甲'],
};

// 격국 정의 — 십신(월지 격 기준) → 격
const GYEOK = {
  정관: {
    name: '정관격', hanja: '正官格', type: '길격',
    desc: '법과 질서, 명예를 중시하는 모범생형 그릇이다. 책임 있는 자리에서 인정받으며, 조직·공직·관리·행정에서 크게 쓰인다. 원칙을 지키는 반듯함이 평생의 무기다.',
    sangsin: '재성(財生官)이 관을 살리고 인성(官印相生)이 받쳐줄 때 격이 완성된다.',
  },
  편관: {
    name: '칠살격', hanja: '七殺格(偏官格)', type: '제화 필요',
    desc: '칼 같은 카리스마와 결단의 그릇이다. 잘 다스리면 큰 권력·무관·전문직으로 우뚝 서고, 못 다스리면 압박과 시련에 휘둘린다. 위기에서 오히려 강해지는 유형.',
    sangsin: '식신으로 살을 제압(食神制殺)하거나 인성으로 살을 돌리면(殺印相生) 큰 인물이 된다.',
  },
  정재: {
    name: '정재격', hanja: '正財格', type: '길격',
    desc: '성실하게 벌어 착실히 쌓는 실속형 그릇이다. 정당한 노력과 신용으로 부를 이루며, 안정적인 생활과 가정을 중시한다. 한 방보다 꾸준함으로 이긴다.',
    sangsin: '식상이 재를 낳고(食傷生財), 일간이 강해 그 재물을 감당할 때 격이 완성된다.',
  },
  편재: {
    name: '편재격', hanja: '偏財格', type: '길격',
    desc: '큰돈과 기회를 다루는 사업·풍류형 그릇이다. 활동과 인맥 속에서 재물이 크게 들고 나며, 수완과 배포가 남다르다. 판을 크게 벌일수록 빛난다.',
    sangsin: '식상생재(食傷生財)에 신왕(身旺)이 받쳐주면 큰 재물을 감당해낸다.',
  },
  식신: {
    name: '식신격', hanja: '食神格', type: '길격',
    desc: '재능과 여유로 베푸는 표현형 그릇이다. 의식주가 풍족하고, 창작·기술·교육·요식에서 빛난다. 즐기면서 일하는 복을 타고났다.',
    sangsin: '식신이 재를 낳으면(食神生財) 복록이 두터워진다.',
  },
  상관: {
    name: '상관격', hanja: '傷官格', type: '제화 필요',
    desc: '틀을 깨는 재능과 창의의 그릇이다. 빼어나고 표현력이 강하지만, 규범·윗사람(官)과 부딪히기 쉽다. 잘 쓰면 천재, 못 쓰면 구설이다.',
    sangsin: '재성으로 재능을 흘리거나(傷官生財) 인성으로 다스리면(傷官佩印) 큰 재능이 된다.',
  },
  정인: {
    name: '정인격', hanja: '正印格', type: '길격',
    desc: '학문과 귀인, 명예의 그릇이다. 배움·문서·자격으로 자리를 얻고, 후덕하고 진중한 평판을 쌓는다. 윗사람과 스승의 덕이 두텁다.',
    sangsin: '관성이 인을 살리면(官印相生) 격이 완성돼 명예가 높아진다.',
  },
  편인: {
    name: '편인격', hanja: '偏印格', type: '편중 주의',
    desc: '남다른 직관과 전문성의 그릇이다. 깊이 파고드는 힘이 탁월하나 편중·고독해지기 쉽다. 종교·역학·예술·기술 등 독특한 분야에서 두각을 낸다.',
    sangsin: '재성으로 편인을 제어(財剋偏印)하거나 관살이 받쳐주면 안정된다.',
  },
  건록: {
    name: '건록격', hanja: '建祿格', type: '신왕',
    desc: '월지에 일간의 뿌리(祿)를 둔 자수성가·독립형 그릇이다. 형제·동료의 힘이 강하고, 누구에게 기대지 않고 제 힘으로 일어선다. 주체성이 곧 재산이다.',
    sangsin: '신왕하니 식상·재성·관성으로 그 힘을 흘리고 다스릴 때 결실을 맺는다.',
  },
  양인: {
    name: '양인격', hanja: '羊刃格', type: '신강·제화 필요',
    desc: '극도로 강한 비겁(羊刃)의 그릇이다. 강건하고 승부에 강하며 폭발력이 크지만, 거칠어지면 사고·다툼으로 터진다. 군·경·운동·외과 등 강한 분야에 어울린다.',
    sangsin: '칠살(편관)로 양인을 다스리면(羊刃駕殺) 큰 실력자·무관이 된다.',
  },
};

export function analyzeGyeokguk(sajuDetail, counts) {
  const p = sajuDetail?.pillars;
  const dayGan = p?.dayGan;
  const monthZhi = p?.month?.zhi;
  if (!dayGan || !monthZhi) return null;
  const c = k => (counts && counts[k]) || 0;

  const hidden = ZHI_HIDDEN[monthZhi] || [];
  if (!hidden.length) return null;

  const jeonggiGod = tenGod(dayGan, hidden[0]); // 월지 정기 십신

  let key, basisStem = hidden[0], byTuchul = false;
  if (jeonggiGod === '비견') { key = '건록'; }
  else if (jeonggiGod === '겁재') { key = '양인'; }
  else {
    // 투출 검사 (년·월·시간, 정기 우선). 비겁은 정격을 이루지 않으므로 제외.
    const cheongan = [p.year?.gan, p.month?.gan, p.time?.gan].filter(Boolean);
    const revealed = hidden.filter(g => cheongan.includes(g) && !['비견', '겁재'].includes(tenGod(dayGan, g)));
    if (revealed.length) { basisStem = revealed[0]; byTuchul = true; }
    key = tenGod(dayGan, basisStem);
  }

  const g = GYEOK[key];
  if (!g) return null;

  // 성격(成格) / 파격(破格) 판정
  let warn = null, good = null;
  switch (key) {
    case '정관':
      if (c('상관')) warn = '사주에 상관(傷官)이 있어 관을 치니(傷官見官) 명예에 흠집·구설이 따르기 쉽다 — 이를 다스리는 인성(印星)이 절실하다.';
      else good = '관을 깨는 상관이 없어 격이 비교적 맑다 — 반듯하게 인정받는 길이 열려 있다.';
      break;
    case '상관':
      if (c('정관')) warn = '정관(正官)이 함께 있어 상관견관(傷官見官) — 재능과 규범이 정면충돌해 굴곡이 크다. 재성으로 흘리거나 인성으로 다스려야 한다.';
      else good = '관과 부딪히지 않아 재능을 마음껏 펼칠 수 있는 구조다.';
      break;
    case '식신':
      if (c('편인')) warn = '편인(偏印)이 식신을 빼앗으니(梟神奪食) 복록이 줄고 일이 막히기 쉽다 — 재성으로 편인을 제어해야 한다.';
      else good = '식신을 빼앗는 편인이 없어 복록이 온전한 구조다.';
      break;
    case '편인':
      if (c('식신')) warn = '식신을 보면 효신탈식(梟神奪食)으로 복이 새기 쉽다 — 재성으로 편인을 눌러주는 것이 관건이다.';
      break;
    case '정인':
      if (c('편재') + c('정재') >= 2) warn = '재성(財星)이 왕성해 인을 깨니(財剋印) 학업·명예·문서가 흔들리기 쉽다 — 재물 욕심을 절제해야 격이 산다.';
      else good = '인을 깨는 재성이 강하지 않아, 배움과 명예가 순조롭게 쌓이는 구조다.';
      break;
    case '정재':
    case '편재':
      if (c('비견') + c('겁재') >= 3) warn = '비겁(比劫)이 강해 재물을 다투니(群劫爭財) 들어와도 새기 쉽다 — 혼자 쥐기보다 협업·분배로 풀어야 한다.';
      else good = '재를 다투는 비겁이 과하지 않아, 번 것을 지킬 수 있는 구조다.';
      break;
    case '편관':
      if (!c('식신') && !c('상관') && !c('편인') && !c('정인'))
        warn = '칠살을 제압할 식상도, 살을 돌릴 인성도 약하다 — 제화(制化) 없는 칠살이라 압박에 시달리기 쉽다. 이 둘을 보강하는 것이 평생 과제.';
      else good = c('식신') || c('상관') ? '식상으로 칠살을 제압하는(食神制殺) 구조 — 시련을 실력으로 바꾸는 힘이 있다.'
        : '인성으로 살을 돌리는(殺印相生) 구조 — 압박을 권위와 지혜로 승화한다.';
      break;
    case '건록':
      if (c('편재') + c('정재') + c('편관') + c('정관') <= 1)
        warn = '힘은 강한데 재성·관성이 약해 흘려보낼 출구가 좁다 — 재·관을 키우는 것이 결실의 열쇠다.';
      else good = '강한 힘을 받아낼 재성·관성이 있어, 자수성가의 결실을 맺는 구조다.';
      break;
    case '양인':
      if (!c('편관') && !c('정관'))
        warn = '양인을 다스릴 관살(官殺)이 없어 그 힘이 사고·다툼으로 터지기 쉽다 — 절제와 규율이 반드시 필요하다.';
      else good = '관살이 양인을 제어하는(羊刃駕殺) 구조 — 강한 기운이 실력과 권위로 모인다.';
      break;
  }

  return {
    key, name: g.name, hanja: g.hanja, type: g.type, desc: g.desc, sangsin: g.sangsin,
    basisStem, byTuchul, jeonggiGod, warn, good,
  };
}

