  setTimeout(()=>{const c=[...document.querySelectorAll('.tcard.back')];c[0]?.click();c[4]?.click();c[8]?.click();},150);
  return 'ok';
})()

(() => {
  const card=document.querySelector('.evidence-card');
  if(!card) return {found:false, tarot:document.querySelectorAll('.tcard.back').length};
  const items=[...card.querySelectorAll('.ev-item')].map(i=>({
    sys:i.querySelector('.ev-sys')?.innerText, badge:i.querySelector('.ev-badge')?.innerText,
    src:i.querySelector('.ev-src')?.getAttribute('href')||'(없음)'
  }));
  return { found:true, count:items.length, items, digitFoot: [...document.querySelectorAll('.nv-foot')].some(p=>/r≈0.04/.test(p.innerText)) };
})()

